Definition ro_addr (a : Z) : Prop :=
  in_ranges (ly_img L) a /\ ~ in_ranges (ly_rw L) a /\ ~ in_ranges (ly_relro L) a.
Definition ro_clear (M : mem) : Prop := forall w : word, ro_addr (bv_unsigned w) -> M w = None.

