Definition nm (M : mem) (a : Z) : Prop :=
  ~ in_ranges (ly_img L) a /\ 0 <= a < 2 ^ 64 /\ M (Z_to_bv 64 a) = None.

Definition W_of (w : Z * Z) (a : Z) : Prop := fst w <= a < snd w.

Record eff (A A' : AS MI) (M M' : mem) (w : Z * Z) (F : Z -> Prop) : Prop := EFF {
  ef_caps   : caps MI A' = caps MI A;
  ef_bigcap : bigcap MI A' = bigcap MI A;
  ef_own    : forall a, owned MI A' a -> owned MI A a \/ nm M a \/ F a;
  ef_frame  : frame_eq (fun a => owned MI A a \/ owned MI A' a \/ nm M a \/ F a \/ W_of w a \/ errno_win L a) M M';
  ef_def    : forall a, 0 <= a < 2 ^ 64 -> M (Z_to_bv 64 a) <> None ->
                M' (Z_to_bv 64 a) <> None \/ owned MI A a \/ F a \/ errno_win L a;
  ef_oimg   : forall a, owned MI A' a -> in_ranges (ly_img L) a -> owned MI A a
}.

