Lemma eff_trans : forall A1 A2 A3 M1 M2 M3 W (F1 F2 : Z -> Prop),
  eff A1 A2 M1 M2 W F1 -> eff A2 A3 M2 M3 W F2 ->
  (forall a, W_of W a -> ~ owned MI A3 a) ->
