Inductive lop : Type := LAdd (p n : Z) | LDel (p : Z).

Fixpoint lapply (lv : list (Z * Z)) (ops : list lop) (lv' : list (Z * Z)) : Prop :=
  match ops with
  | [] => lv' = lv
  | LAdd p n :: r => exists lv1, live_add p n lv lv1 /\ lapply lv1 r lv'
  | LDel p :: r => exists lv1, live_del p lv lv1 /\ lapply lv1 r lv'
  end.

Lemma lapply_app : forall ops1 ops2 lv lv1 lv',
  lapply lv ops1 lv1 -> lapply lv1 ops2 lv' -> lapply lv (ops1 ++ ops2) lv'.
