Arguments nm {L}.
Arguments eff {AC SEGS L} MI.
Arguments eff_refl {AC SEGS L} MI.
Arguments eff_trans {AC SEGS L} MI.
Arguments eff_weaken {AC SEGS L} MI.
Arguments eff_store {AC SEGS L} MI.
Arguments eff_of_new {AC SEGS L} MI.
Arguments eff_of_del {AC SEGS L} MI.

Section Bundles.
Context {AC : AllocCeiling}.
Variable SEGS : list Segment.
Variable L : Layout.
Variable MI : MallocIface SEGS L.
Variable ST : StaticsIface SEGS L.

Definition above_sp (A : AS MI) (sp a n : Z) : Prop :=
  sp <= a /\ a + n <= 2 ^ 47 /\ forall i, 0 <= i < n -> ~ owned MI A (a + i).

Record callB (A : AS MI) (s : SX ST) (R : bvmap 5 word) (M : mem) (model : Model) (sp ret S : Z) : Prop := CALLB {
  cb_ainv : ainv MI A M model;
  cb_mstd : mstd model;
  cb_roc  : img_ro_clear L M;
  cb_sx   : sx_inv ST s M;
  cb_sxh  : sx_handler_set ST s;
  cb_regs : call_regs L R sp ret;
  cb_ceil : alloc_ceiling + S <= sp;
  cb_room : stack_room SEGS M sp S;
  cb_win  : forall a, zwin (sp - S) sp a -> ~ owned MI A a /\ ~ sx_region ST a;
  cb_own_sx : forall a, owned MI A a -> ~ sx_region ST a;
  cb_err_sx : forall a, errno_win L a -> ~ sx_region ST a
}.

Record retB (A' : AS MI) (s : SX ST) (R R' : bvmap 5 word) (M' : mem) (model model' : Model) : Prop := RETB {
  rb_ainv : ainv MI A' M' model';
  rb_mstd : mstd model';
  rb_fs   : m_fs model' = m_fs model;
  rb_fds  : m_fds model' = m_fds model;
  rb_sx   : sx_inv ST s M';
  rb_kept : kept R R'
}.

Definition roomL (A : AS MI) (lv : list (Z * Z)) (n : Z) : Prop :=
  (n < BIG MI ->
     count_class_f (size_class MI) (BIG MI) lv (size_class MI n) + 1 <= caps MI A (size_class MI n)
     /\ count_class_f (size_class MI) (BIG MI) lv (size_class MI n + 1) + 1 <= caps MI A (size_class MI n + 1))
  /\ (BIG MI <= n -> big_bytes_f (round_big MI) (BIG MI) lv + round_big MI n <= bigcap MI A).

End Bundles.

Arguments above_sp {AC SEGS L} MI _ _ _ _.
Arguments callB {AC SEGS L} MI ST _ _ _ _ _ _ _ _.
Arguments retB {AC SEGS L} MI ST _ _ _ _ _ _ _.
Arguments roomL {AC SEGS L} MI _ _ _.
